// Generated by OrchestKit Claude Plugin
// Created: 2026-08-09

/**
 * Regression: exactly ONE "[Previous Session Handoff]" block per session (#3329)
 *
 * ork ships two independent across-time handoff loops that opened with the
 * SAME marker:
 *
 *   global YAML : lifecycle/session-handoff-generator (SessionEnd)
 *                 -> lifecycle/session-handoff-injector (SessionStart)
 *                 store: ~/.claude/analytics/handoffs/<sha256(projectDir)>/latest.yaml
 *
 *   repo-local  : stop/handoff-writer (Stop)
 *                 -> prompt/handoff-injector (UserPromptSubmit, runOnce)
 *                 store: <projectDir>/.claude/HANDOFF.md
 *
 * Nothing coordinated them, so a session with both stores populated injected
 * the marker TWICE. #3329 defers deleting the global pair; what it cannot
 * defer is the duplication, and it cannot defer it precisely because the
 * issue's own first step (teach the repo-local injector to fall back to the
 * global store) makes the duplicate IDENTICAL rather than merely redundant.
 *
 * These tests use a real temp HOME and a real temp project — the claim is a
 * filesystem primitive (exclusive create) and mocking fs would test nothing.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdtempSync, mkdirSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createHash } from 'node:crypto';

import { sessionHandoffInjector } from '../../lifecycle/session-handoff-injector.js';
import { handoffInjector } from '../../prompt/handoff-injector.js';
import type { HookInput, HookResult } from '../../types.js';
import { createTestContext } from '../fixtures/test-context.js';

const MARKER = '[Previous Session Handoff]';
const SESSION_ID = 'sess-3329';

let home: string;
let projectDir: string;
let envHome: string | undefined;
let envPluginData: string | undefined;

/** The additionalContext a hook result carries, or '' when it carries none. */
function contextOf(result: HookResult): string {
  const hso = (result as { hookSpecificOutput?: { additionalContext?: unknown } })
    .hookSpecificOutput;
  return typeof hso?.additionalContext === 'string' ? hso.additionalContext : '';
}

function input(): HookInput {
  return {
    tool_name: '',
    session_id: SESSION_ID,
    tool_input: {},
    project_dir: projectDir,
  } as HookInput;
}

/** Populate the GLOBAL YAML store for this project. */
function writeGlobalHandoff(body: string): void {
  const hash = createHash('sha256').update(projectDir).digest('hex').slice(0, 12);
  const dir = join(home, '.claude', 'analytics', 'handoffs', hash);
  mkdirSync(dir, { recursive: true });
  writeFileSync(join(dir, 'latest.yaml'), body, 'utf8');
}

/** Populate the REPO-LOCAL store for this project. */
function writeLocalHandoff(body: string): void {
  mkdirSync(join(projectDir, '.claude'), { recursive: true });
  writeFileSync(join(projectDir, '.claude', 'HANDOFF.md'), body, 'utf8');
}

beforeEach(() => {
  home = mkdtempSync(join(tmpdir(), 'ork-3329-home-'));
  projectDir = mkdtempSync(join(tmpdir(), 'ork-3329-proj-'));
  envHome = process.env.HOME;
  envPluginData = process.env.CLAUDE_PLUGIN_DATA;
  process.env.HOME = home;
  // Keep once-flags/claims inside the temp project rather than a shared tree.
  delete process.env.CLAUDE_PLUGIN_DATA;
});

afterEach(() => {
  if (envHome === undefined) delete process.env.HOME;
  else process.env.HOME = envHome;
  if (envPluginData === undefined) delete process.env.CLAUDE_PLUGIN_DATA;
  else process.env.CLAUDE_PLUGIN_DATA = envPluginData;
  rmSync(home, { recursive: true, force: true });
  rmSync(projectDir, { recursive: true, force: true });
});

describe('handoff injection is single-shot per session (#3329)', () => {
  it('injects the marker exactly once when BOTH stores are populated', () => {
    writeGlobalHandoff('status: partial\nnext: finish the rebase\n');
    writeLocalHandoff('# Handoff\n\nPicked up the rebase, three commits to go.\n');

    const ctx = createTestContext({ projectDir });
    const fromSessionStart = contextOf(sessionHandoffInjector(input(), ctx));
    const fromPrompt = contextOf(handoffInjector(input(), ctx));

    const injections = [fromSessionStart, fromPrompt].filter((c) => c.includes(MARKER));
    expect(
      injections.length,
      `expected exactly 1 handoff injection, got ${injections.length}`,
    ).toBe(1);
  });

  it('prefers the repo-local store when both are present', () => {
    writeGlobalHandoff('status: partial\nnext: from the global yaml store\n');
    writeLocalHandoff('# Handoff\n\nfrom the repo-local markdown store\n');

    const ctx = createTestContext({ projectDir });
    const fromSessionStart = contextOf(sessionHandoffInjector(input(), ctx));
    const fromPrompt = contextOf(handoffInjector(input(), ctx));

    expect(fromSessionStart).not.toContain(MARKER);
    expect(fromPrompt).toContain('from the repo-local markdown store');
  });

  it('falls back to the global store when no repo-local handoff exists', () => {
    writeGlobalHandoff('status: partial\nnext: only the global yaml store exists\n');

    const ctx = createTestContext({ projectDir });
    // SessionStart is skipped here on purpose: this asserts the prompt-side
    // re-home (#3329 "RE-HOME FIRST"), i.e. that the repo-local injector can
    // serve the global store on its own once the SessionStart hook is deleted.
    const fromPrompt = contextOf(handoffInjector(input(), ctx));

    expect(fromPrompt).toContain(MARKER);
    expect(fromPrompt).toContain('only the global yaml store exists');
  });

  it('injects nothing at all when neither store is populated', () => {
    const ctx = createTestContext({ projectDir });
    expect(contextOf(sessionHandoffInjector(input(), ctx))).not.toContain(MARKER);
    expect(contextOf(handoffInjector(input(), ctx))).not.toContain(MARKER);
  });

  it('does not re-inject when the SessionStart hook runs twice in one session', () => {
    writeGlobalHandoff('status: partial\nnext: resume from the global store\n');

    const ctx = createTestContext({ projectDir });
    const first = contextOf(sessionHandoffInjector(input(), ctx));
    const second = contextOf(sessionHandoffInjector(input(), ctx));

    expect(first).toContain(MARKER);
    expect(second).not.toContain(MARKER);
  });
});
